{"Table":"kersef_tb_user_xp_log","Create Table":"CREATE TABLE `kersef_tb_user_xp_log` (\n  `id` varchar(36) NOT NULL,\n  `amount` int(11) NOT NULL,\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\n  `guildId` varchar(255) NOT NULL,\n  `userId` varchar(255) NOT NULL,\n  PRIMARY KEY (`id`),\n  KEY `FK_log_user_guild` (`guildId`),\n  KEY `FK_log_user_user` (`userId`),\n  CONSTRAINT `FK_log_user_guild` FOREIGN KEY (`guildId`) REFERENCES `kersef_tb_user` (`guildId`) ON DELETE CASCADE ON UPDATE CASCADE,\n  CONSTRAINT `FK_log_user_user` FOREIGN KEY (`userId`) REFERENCES `kersef_tb_user` (`userId`) ON DELETE CASCADE ON UPDATE CASCADE\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci","json":{"name":"kersef_tb_user_xp_log.sql","path":"files/sql/rod/kersef_tb_user_xp_log.sql","sha":"4b97bc50f31af213e31be972d29a61b75c4b77af","size":1217151,"url":"https://api.github.com/repos/rodcordeiro/shares/contents/files/sql/rod/kersef_tb_user_xp_log.sql?ref=master","html_url":"https://github.com/rodcordeiro/shares/blob/master/files/sql/rod/kersef_tb_user_xp_log.sql","git_url":"https://api.github.com/repos/rodcordeiro/shares/git/blobs/4b97bc50f31af213e31be972d29a61b75c4b77af","download_url":"https://raw.githubusercontent.com/rodcordeiro/shares/master/files/sql/rod/kersef_tb_user_xp_log.sql","type":"file","content":"","encoding":"none","_links":{"self":"https://api.github.com/repos/rodcordeiro/shares/contents/files/sql/rod/kersef_tb_user_xp_log.sql?ref=master","git":"https://api.github.com/repos/rodcordeiro/shares/git/blobs/4b97bc50f31af213e31be972d29a61b75c4b77af","html":"https://github.com/rodcordeiro/shares/blob/master/files/sql/rod/kersef_tb_user_xp_log.sql"}},"pairedItem":{"item":31},"index":31}